    //Checks if InterruptController.comp_Reg_IF.comp_Top_CSC.DefaultInterface_rd_en == 0, then the value of the enable_int_0 remains the same
    property DefaultInterface_bf_enable_int_0_write_dummy;
    @(posedge InterruptController.HCLK_i)
    disable iff(!InterruptController.HRESET_n_i)
        (( (InterruptController.comp_Reg_IF.comp_Top_CSC.DefaultInterface_wr_en == 0) ) 
	|->
	  ##1
	 (InterruptController.comp_Reg_IF.comp_Top_CSC.comp_Top_CSC_DefaultInterface.DefaultInterface_BF_enable_int_0_output ==  $past(InterruptController.comp_Reg_IF.comp_Top_CSC.comp_Top_CSC_DefaultInterface.DefaultInterface_BF_enable_int_0_output)) );
    endproperty
