	|->
	 (  ##1
	 (InterruptController.comp_Reg_IF.comp_Top_CSC.comp_Top_CSC_DefaultInterface.DefaultInterface_BF_enable_int_0_output ==  $past(InterruptController.comp_Reg_IF.comp_Top_CSC.DefaultInterface_data_in[0]))  && 
